-- Siteplan Pesona Angrek (101 kavling) dan Mutiara Ville (229 kavling)
-- Import pada database aplikasi melalui phpMyAdmin > Import.
-- ID lokasi disesuaikan otomatis. Data yang sudah ada tidak ditimpa.
-- Teks SVG memakai literal hex agar aman dari perbedaan SQL mode.
SET NAMES utf8mb4;
START TRANSACTION;

-- Pesona Angrek
SET @siteplan_urutan = (SELECT COALESCE(MAX(`urutan`), 0) + 1 FROM `lokasi_kavling`);
SET @siteplan_exists = (SELECT COUNT(*) FROM `lokasi_kavling` WHERE `nama_kavling` = CONVERT(0x5065736f6e6120416e6772656b USING utf8mb4) COLLATE utf8mb4_unicode_ci);
