SET @siteplan_lokasi = (SELECT `id` FROM `lokasi_kavling` WHERE `nama_kavling` = CONVERT(0x5065736f6e6120416e6772656b USING utf8mb4) COLLATE utf8mb4_unicode_ci ORDER BY `id` LIMIT 1);

