-- Verifikasi: Pesona Angrek = 101, Mutiara Ville = 229.
SELECT l.id, l.nama_kavling, COUNT(k.id) AS jumlah_kavling,
    (SELECT COUNT(*) FROM master_svg s WHERE s.id_lokasi = l.id) AS jumlah_master_svg
FROM lokasi_kavling l LEFT JOIN kavling_peta k ON k.id_lokasi = l.id
WHERE l.nama_kavling IN ('Pesona Angrek', 'Mutiara Ville')
GROUP BY l.id, l.nama_kavling;
